(function(){
  document.documentElement.className += ' js';
  try {
    var lang = localStorage.getItem('lang');
    if (lang === 'en') { document.documentElement.lang = 'en'; document.documentElement.dir = 'ltr'; }
    var theme = localStorage.getItem('theme');
    document.documentElement.setAttribute('data-theme', theme === 'Light' || theme === 'light' ? 'light' : (theme ? 'dark' : (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark')));
  } catch (e) { document.documentElement.setAttribute('data-theme', 'dark'); }
})();
