head.b:skin:
/*
=========================================
Template: WeRList99 - Hub v6.0
Modern Blogger magazine + developer hub
=========================================
*/
:root{
  color-scheme:dark;
  --primary:#818cf8;--primary-strong:#6366f1;--secondary:#a78bfa;--accent:#22d3ee;
  --bg:#080d18;--bg-soft:#0c1322;--surface:#111a2b;--surface-2:#182338;
  --text:#f3f6fc;--muted:#9aa9bd;--line:rgba(148,163,184,.18);
  --success:#34d399;--danger:#fb7185;--warning:#fbbf24;
  --shadow:0 18px 50px rgba(0,0,0,.22);--shadow-hover:0 24px 60px rgba(0,0,0,.32);
  --radius:20px;--radius-sm:12px;--nav-height:72px;
}
html[data-theme='light']{
  color-scheme:light;
  --primary:#4f46e5;--primary-strong:#4338ca;--secondary:#7c3aed;--accent:#0891b2;
  --bg:#f5f7fc;--bg-soft:#eef2f9;--surface:#fff;--surface-2:#f0f3fa;
  --text:#172033;--muted:#637086;--line:rgba(71,85,105,.17);
  --success:#059669;--danger:#e11d48;--warning:#d97706;
  --shadow:0 16px 42px rgba(38,51,77,.08);--shadow-hover:0 22px 50px rgba(38,51,77,.14);
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;scroll-padding-top:calc(var(--nav-height) + 22px)}
body{font-family:'Tajawal','Cairo',Arial,sans-serif;background:var(--bg);color:var(--text);line-height:1.8;direction:rtl;min-height:100vh;overflow-x:hidden;transition:background-color .25s,color .25s}
body::before{content:'';position:fixed;inset:0;pointer-events:none;z-index:-1;background:radial-gradient(circle at 85% 5%,rgba(99,102,241,.1),transparent 28%),radial-gradient(circle at 10% 35%,rgba(34,211,238,.055),transparent 25%)}
a{color:inherit;text-decoration:none}img{display:block;max-width:100%;height:auto}ul{list-style:none}
button,input,select{font:inherit}button{color:inherit}button,a{-webkit-tap-highlight-color:transparent}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:3px}
::selection{background:rgba(99,102,241,.35);color:var(--text)}
.container{width:min(1180px,calc(100% - 40px));margin-inline:auto}
.sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.skip-link{position:fixed;top:10px;inset-inline-start:16px;z-index:3000;background:var(--primary-strong);color:#fff;padding:10px 18px;border-radius:10px;transform:translateY(-150%)}
.skip-link:focus{transform:none}
[hidden]{display:none!important}
#projects,#stack,#links,#posts{scroll-margin-top:calc(var(--nav-height) + 22px)}
.progress-bar{position:fixed;top:0;inset-inline-start:0;height:3px;width:0;z-index:2200;background:linear-gradient(90deg,var(--primary),var(--accent));pointer-events:none}

/* Shared controls */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:44px;padding:10px 20px;border:1px solid transparent;border-radius:12px;font-weight:700;cursor:pointer;transition:transform .2s,background .2s,border-color .2s,box-shadow .2s}
.btn:hover{transform:translateY(-2px)}
.btn-primary{background:linear-gradient(135deg,var(--primary-strong),var(--secondary));color:#fff;box-shadow:0 10px 25px rgba(99,102,241,.22)}
.btn-primary:hover{box-shadow:0 14px 32px rgba(99,102,241,.34)}
.btn-ghost{background:var(--surface);border-color:var(--line);color:var(--text)}
.btn-ghost:hover{border-color:var(--primary);color:var(--primary)}
.icon-btn{width:42px;height:42px;display:inline-flex;align-items:center;justify-content:center;gap:6px;background:var(--surface-2);border:1px solid var(--line);border-radius:11px;cursor:pointer;transition:.2s}
.icon-btn:hover{color:var(--primary);border-color:var(--primary);background:var(--surface)}

/* Navigation */
.navbar{position:sticky;top:0;z-index:1000;height:var(--nav-height);background:var(--bg);background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}
.nav-container{height:100%;display:flex;align-items:center;gap:24px}
.brand{display:flex;align-items:center;gap:11px;flex-shrink:0}
.brand-mark{width:41px;height:41px;display:grid;place-items:center;border-radius:13px;background:linear-gradient(135deg,var(--primary-strong),var(--secondary));color:#fff;font:700 1.2rem 'JetBrains Mono',monospace;box-shadow:0 8px 20px rgba(99,102,241,.24)}
.brand-copy{display:flex;flex-direction:column;line-height:1.2}
.brand-copy strong{font-family:'Cairo',sans-serif;font-size:1.12rem;letter-spacing:.2px}
.brand-copy small{color:var(--muted);font-size:.68rem;font-weight:500;letter-spacing:1.5px;text-transform:uppercase}
.nav-links{display:flex;align-items:center;gap:4px;margin-inline-start:auto}
.nav-links a{display:flex;align-items:center;gap:7px;color:var(--muted);font-weight:600;padding:8px 12px;border-radius:10px;font-size:.9rem;transition:.2s}
.nav-links a:hover{color:var(--text);background:var(--surface-2)}
.nav-links a.active{color:var(--primary);background:rgba(99,102,241,.11)}
.nav-tools{display:flex;align-items:center;gap:7px}
.lang-toggle{width:auto;padding-inline:11px;font-size:.78rem;font-weight:700}
.menu-toggle{display:none}
html[dir='ltr'] .nav-links,html[dir='ltr'] .brand-copy{direction:ltr}

/* Homepage hero */
.header{position:relative;padding:70px 0 62px;border-bottom:1px solid var(--line);overflow:hidden}
.header::before{content:'';position:absolute;width:460px;height:460px;top:-210px;inset-inline-end:-120px;border-radius:50%;background:rgba(99,102,241,.15);filter:blur(90px);pointer-events:none}
.hero-grid{display:grid;grid-template-columns:1.12fr .88fr;gap:70px;align-items:center;position:relative}
.hero-eyebrow{display:inline-flex;align-items:center;gap:8px;color:var(--primary);background:rgba(99,102,241,.1);border:1px solid rgba(99,102,241,.22);border-radius:999px;padding:5px 13px;font-size:.8rem;font-weight:700;margin-bottom:18px}
.status-dot{width:8px;height:8px;border-radius:50%;background:var(--success);box-shadow:0 0 0 5px rgba(52,211,153,.1)}
.logo{font-family:'Cairo',sans-serif;font-size:clamp(2.15rem,4.8vw,4.15rem);font-weight:900;line-height:1.3;letter-spacing:-1.5px;margin-bottom:16px}
.logo .gradient-text,.gradient-text{background:linear-gradient(110deg,var(--primary),var(--accent));-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:var(--primary)}
.hero-bio{color:var(--muted);max-width:650px;font-size:1.07rem;line-height:1.95;margin-bottom:24px}
.hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:25px}
.hero-badges{display:flex;flex-wrap:wrap;gap:8px}
.chip{display:inline-flex;align-items:center;gap:6px;background:var(--surface);border:1px solid var(--line);padding:4px 11px;border-radius:999px;font-size:.77rem;color:var(--muted)}
.chip i{color:var(--primary)}
.header-social{display:flex;gap:8px;margin-top:20px}
.header-social a{width:36px;height:36px;display:grid;place-items:center;color:var(--muted);border-radius:9px;transition:.2s}
.header-social a:hover{background:var(--surface-2);color:var(--primary);transform:translateY(-2px)}
.hero-visual{position:relative;direction:ltr;max-width:440px;margin-inline:auto;width:100%}
.code-window{background:var(--surface);border:1px solid var(--line);border-radius:22px;box-shadow:var(--shadow);overflow:hidden;transform:rotate(1.5deg)}
.code-top{height:48px;display:flex;align-items:center;gap:7px;padding:0 18px;border-bottom:1px solid var(--line);background:var(--surface-2)}
.code-top span{width:10px;height:10px;border-radius:50%;background:#fb7185}.code-top span:nth-child(2){background:#fbbf24}.code-top span:nth-child(3){background:#34d399}
.code-top b{margin-left:auto;color:var(--muted);font:500 .72rem 'JetBrains Mono',monospace}
.code-content{padding:25px;font:400 .88rem/2 'JetBrains Mono',monospace;color:#c4b5fd;white-space:pre-wrap;word-break:break-word}
html[data-theme='light'] .code-content{color:#6d28d9}
.code-content .code-key{color:#22d3ee}.code-content .code-value{color:#fbbf24}.code-content .code-text{color:var(--text)}
.profile-float{position:absolute;bottom:-28px;right:-20px;display:flex;align-items:center;gap:12px;background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:12px 16px;box-shadow:var(--shadow);direction:rtl}
.profile-float img{width:48px;height:48px;border-radius:50%;object-fit:cover;border:2px solid var(--primary)}
.profile-float strong{display:block;font-size:.9rem}.profile-float small{display:flex;align-items:center;gap:5px;color:var(--muted);font-size:.72rem}

/* Search dialog */
.search-overlay{position:fixed;inset:0;z-index:1800;display:none;align-items:flex-start;justify-content:center;background:rgba(3,7,18,.82);backdrop-filter:blur(8px);padding:12vh 20px 30px}
.search-overlay.open{display:flex}
.search-dialog{width:100%;max-width:620px;background:var(--surface);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow-hover);padding:22px;animation:dialog-in .2s ease}
@keyframes dialog-in{from{opacity:0;transform:translateY(-12px) scale(.98)}to{opacity:1;transform:none}}
.search-dialog-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}
.search-dialog-head h2{font-size:1.15rem;display:flex;gap:9px;align-items:center}.search-dialog-head h2 i{color:var(--primary)}
.search-box{display:flex;background:var(--bg-soft);border:1px solid var(--line);border-radius:13px;overflow:hidden}
.search-box:focus-within{border-color:var(--primary);box-shadow:0 0 0 3px rgba(99,102,241,.12)}
.search-box input{flex:1;min-width:0;background:transparent;border:0;color:var(--text);padding:13px 16px;outline:0}
.search-box button{border:0;background:var(--primary-strong);color:#fff;padding:0 22px;cursor:pointer}
.search-hint{color:var(--muted);font-size:.78rem;margin-top:10px}
.search-suggestions{display:flex;align-items:center;flex-wrap:wrap;gap:7px;margin-top:16px}
.search-suggestions>span{color:var(--muted);font-size:.8rem}.search-suggestions a{font-size:.76rem;padding:4px 10px;border:1px solid var(--line);border-radius:999px;color:var(--muted)}
.search-suggestions a:hover{color:var(--primary);border-color:var(--primary)}

/* Main layout and section headings */
.main-wrapper{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:30px;padding-top:42px;padding-bottom:30px;align-items:start}
.content{min-width:0}.hub-section{margin-bottom:44px}
.section-title{display:flex;align-items:center;gap:11px;font-family:'Cairo',sans-serif;font-size:1.45rem;line-height:1.5;margin-bottom:9px;font-weight:800}
.section-title>i{color:var(--primary)}
.section-title .count-badge{margin-inline-start:auto;font:500 .76rem 'Tajawal',sans-serif;background:var(--surface);border:1px solid var(--line);padding:3px 11px;border-radius:999px;color:var(--muted)}
.section-subtitle{color:var(--muted);font-size:.9rem;margin-bottom:24px}
.section-heading{margin-bottom:24px;border-bottom:1px solid var(--line);padding-bottom:18px}
.section-heading .section-title{margin-bottom:5px}.section-heading .section-subtitle{margin:0}
.cat-strip{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:0 0 24px}
.cat-strip>span{color:var(--muted);font-size:.82rem;margin-inline-end:3px}
.cat-chip{background:var(--surface);border:1px solid var(--line);border-radius:999px;padding:5px 13px;font-size:.8rem;color:var(--muted);transition:.2s}
.cat-chip:hover{background:rgba(99,102,241,.1);color:var(--primary);border-color:var(--primary)}

/* Post cards */
.home-posts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin-bottom:28px}
.home-posts .article-card{margin:0;height:100%;display:flex;flex-direction:column}
.home-posts .article-card:first-child{grid-column:1/-1;display:grid;grid-template-columns:1.12fr .88fr}
.home-posts .article-card:first-child .post-media{height:100%;min-height:330px}
.home-posts .article-card:first-child .post-content{justify-content:center;padding:32px}
.home-posts .article-card:first-child .post-title{font-size:1.85rem}
.article-card{background:var(--surface);border-radius:var(--radius);overflow:hidden;margin-bottom:25px;border:1px solid var(--line);box-shadow:0 1px 0 rgba(255,255,255,.02);transition:transform .25s,border-color .25s,box-shadow .25s}
.home-posts .article-card:hover{transform:translateY(-5px);box-shadow:var(--shadow-hover);border-color:rgba(99,102,241,.5)}
.post-media{display:block;position:relative;height:205px;overflow:hidden;background:var(--surface-2)}
.post-thumbnail{width:100%;height:100%;object-fit:cover;transition:transform .45s}
.article-card:hover .post-thumbnail{transform:scale(1.035)}
.post-thumb-placeholder{height:100%;display:grid;place-items:center;color:var(--primary);font-size:2.6rem;background:linear-gradient(135deg,rgba(99,102,241,.13),rgba(34,211,238,.05))}
.post-content{padding:23px;display:flex;flex-direction:column;flex:1}
.post-meta{display:flex;flex-wrap:wrap;gap:10px 14px;align-items:center;margin-bottom:12px;font-size:.78rem;color:var(--muted)}
.post-meta>span{display:inline-flex;align-items:center;gap:5px}.post-meta i{color:var(--primary)}
.post-meta .category{gap:4px}.post-meta .category a{background:rgba(99,102,241,.11);color:var(--primary);padding:2px 9px;border-radius:999px}
.post-title{font-family:'Cairo',sans-serif;font-size:1.22rem;line-height:1.65;margin-bottom:10px;font-weight:800;overflow-wrap:anywhere}
.post-title a:hover{color:var(--primary)}
.post-excerpt{color:var(--muted);font-size:.9rem;line-height:1.85;margin-bottom:19px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.read-more{display:inline-flex;align-items:center;gap:8px;color:var(--primary);font-weight:700;font-size:.87rem;margin-top:auto;align-self:flex-start;transition:gap .2s}
.read-more:hover{gap:13px}

/* Single post and pages */
.breadcrumb{display:flex;flex-wrap:wrap;gap:7px;align-items:center;color:var(--muted);font-size:.8rem;margin-bottom:20px}
.breadcrumb a{color:var(--primary)}.breadcrumb .sep{opacity:.5}
.post-single{overflow:visible;background:transparent;border:0}
.post-single:hover{transform:none}.single-header{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius) var(--radius) 0 0;padding:30px 34px 26px}
.single-header .post-title{font-size:clamp(1.65rem,3vw,2.35rem);margin:8px 0 13px;line-height:1.55}
.single-meta{margin-top:18px;margin-bottom:0}
.single-excerpt{color:var(--muted);font-size:1rem;margin:0}
.author-avatar{width:25px;height:25px;border-radius:50%;object-fit:cover}
.single-cover{width:100%;max-height:480px;object-fit:cover;border-inline:1px solid var(--line)}
.single-content{background:var(--surface);border:1px solid var(--line);border-radius:0 0 var(--radius) var(--radius);padding:30px 34px}
.single-header+.single-content{border-radius:0 0 var(--radius) var(--radius)}
.post-tools{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;padding-bottom:20px;margin-bottom:26px;border-bottom:1px solid var(--line)}
.font-tools{display:flex;gap:7px;align-items:center;color:var(--muted);font-size:.8rem}
.tool-btn{min-width:38px;height:36px;padding:0 10px;background:var(--surface-2);border:1px solid var(--line);color:var(--text);border-radius:9px;cursor:pointer;font-weight:700;transition:.2s}
.tool-btn:hover{border-color:var(--primary);color:var(--primary)}
.toc{background:var(--bg-soft);border:1px solid var(--line);border-radius:13px;padding:13px 17px;margin-bottom:28px}
.toc summary{cursor:pointer;font-weight:700;color:var(--primary)}
.toc-list{display:flex;flex-direction:column;gap:3px;margin-top:11px}
.toc-list a{color:var(--muted);font-size:.87rem;padding:5px 10px;border-inline-start:2px solid var(--line);transition:.2s}
.toc-list a:hover,.toc-list a.active{color:var(--primary);border-color:var(--primary);background:rgba(99,102,241,.06)}
.toc-list a.lvl-3{margin-inline-start:16px;font-size:.82rem}
.post-body{font-size:1.04rem;line-height:2.05;overflow-wrap:break-word}
.post-body h2,.post-body h3,.post-body h4{font-family:'Cairo',sans-serif;margin:34px 0 14px;line-height:1.55;scroll-margin-top:95px}
.post-body h2{font-size:1.55rem}.post-body h3{font-size:1.28rem}.post-body h4{font-size:1.12rem}
.post-body p{margin-bottom:19px}.post-body img{border-radius:13px;margin:22px auto}.post-body a{color:var(--primary);text-decoration:underline;text-underline-offset:3px}
.post-body blockquote{background:var(--bg-soft);border-inline-start:4px solid var(--primary);padding:18px 22px;margin:24px 0;border-radius:0 12px 12px 0;color:var(--muted)}
.post-body code{direction:ltr;unicode-bidi:embed;background:var(--bg-soft);padding:2px 7px;border-radius:5px;font-family:'JetBrains Mono',monospace;color:var(--accent);font-size:.88em}
.post-body pre{position:relative;direction:ltr;text-align:left;background:#080d18;color:#e2e8f0;padding:48px 20px 20px;border-radius:13px;overflow:auto;margin:24px 0;border:1px solid var(--line);line-height:1.75;tab-size:2}
.post-body pre code{color:#e2e8f0;background:none;padding:0;font-size:.85rem}.post-body ul{list-style:disc}.post-body ol{list-style:decimal}
.post-body ul,.post-body ol{margin:15px 25px 20px;padding-inline-start:20px}.post-body li{margin-bottom:8px}
.post-body table{width:100%;border-collapse:collapse;display:block;overflow:auto;margin:20px 0}.post-body th,.post-body td{border:1px solid var(--line);padding:10px 13px;text-align:start}.post-body th{background:var(--surface-2)}
.copy-code{position:absolute;top:9px;right:9px;background:#1e293b;color:#e2e8f0;border:1px solid #475569;border-radius:7px;padding:4px 10px;font:600 .72rem 'Tajawal',sans-serif;cursor:pointer}
.copy-code:hover{background:#334155}
.share-buttons{display:flex;gap:9px;align-items:center;flex-wrap:wrap;padding:22px 0;margin-top:30px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.share-buttons>span{font-weight:700;margin-inline-end:auto;font-size:.9rem}
.share-btn{width:40px;height:40px;display:grid;place-items:center;border-radius:10px;color:#fff;transition:transform .2s,filter .2s;border:0;cursor:pointer;font-size:.95rem}
.share-btn:hover{transform:translateY(-3px);filter:brightness(1.12)}
.share-btn.facebook{background:#1877f2}.share-btn.twitter{background:#111}.share-btn.whatsapp{background:#25d366}.share-btn.telegram{background:#0088cc}.share-btn.linkedin{background:#0a66c2}.share-btn.native,.share-btn.copy{background:var(--primary-strong)}
.related-posts{margin-top:34px}.related-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.related-card{display:flex;background:var(--surface);border-radius:13px;overflow:hidden;border:1px solid var(--line);transition:.2s;min-width:0}
.related-card:hover{border-color:var(--primary);transform:translateY(-2px)}
.related-card img,.related-thumb-placeholder{width:105px;min-height:105px;object-fit:cover;flex-shrink:0}.related-thumb-placeholder{display:grid;place-items:center;background:var(--surface-2);color:var(--primary)}
.related-card-content{padding:13px;display:flex;align-items:center}.related-card h4{font-size:.88rem;line-height:1.6}.related-card h4 a:hover{color:var(--primary)}
.comments-wrap{margin-top:34px}.comments{background:var(--surface);padding:25px;border:1px solid var(--line);border-radius:var(--radius)}
.comments-title{font-size:1.25rem;margin-bottom:20px;display:flex;align-items:center;gap:9px}.comments-title i{color:var(--primary)}
.comment-form iframe{max-width:100%}.comments-content{overflow-wrap:anywhere}

/* GitHub developer hub */
.gh-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:20px}
.gh-stat{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:15px 12px;text-align:center}
.gh-stat b{display:block;font:700 1.45rem 'JetBrains Mono',monospace;color:var(--primary);line-height:1.4}.gh-stat span{font-size:.76rem;color:var(--muted)}
.project-controls{display:grid;grid-template-columns:minmax(160px,1fr) auto auto;gap:9px;margin-bottom:20px}
.field,.select-field{background:var(--surface);border:1px solid var(--line);border-radius:11px;color:var(--text);min-height:43px;padding:8px 12px;outline:0}
.field:focus,.select-field:focus{border-color:var(--primary)}.select-field{cursor:pointer;max-width:160px}
.search-field{position:relative}.search-field i{position:absolute;inset-inline-start:13px;top:50%;transform:translateY(-50%);color:var(--muted);font-size:.85rem}.search-field .field{width:100%;padding-inline-start:35px}
.gh-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.gh-card{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:19px;display:flex;flex-direction:column;transition:.22s;position:relative;min-width:0}
.gh-card:hover{transform:translateY(-4px);border-color:rgba(99,102,241,.55);box-shadow:var(--shadow)}
.gh-head{display:flex;align-items:flex-start;gap:9px;margin-bottom:10px}.gh-head>i{color:var(--primary);margin-top:6px}.gh-head h3{font:600 .95rem/1.6 'JetBrains Mono',monospace;overflow-wrap:anywhere;direction:ltr;text-align:start}.gh-head h3 a:hover{color:var(--primary)}
.gh-desc{color:var(--muted);font-size:.84rem;flex:1;margin-bottom:15px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.gh-foot{display:flex;align-items:center;gap:11px;font-size:.75rem;color:var(--muted);flex-wrap:wrap}.gh-foot .lang{display:flex;align-items:center;gap:5px}.lang-dot{width:9px;height:9px;border-radius:50%;display:inline-block}
.gh-topics{display:flex;flex-wrap:wrap;gap:5px;margin-top:12px}.gh-topic{background:var(--bg-soft);border:1px solid var(--line);border-radius:999px;padding:1px 8px;font-size:.67rem;color:var(--muted)}
.gh-updated{font-size:.69rem;color:var(--muted);margin-top:12px;padding-top:10px;border-top:1px solid var(--line)}
.empty-state,.error-state{grid-column:1/-1;text-align:center;padding:35px 20px;background:var(--surface);border:1px dashed var(--line);border-radius:15px;color:var(--muted)}
.empty-state i,.error-state i{display:block;font-size:1.7rem;color:var(--primary);margin-bottom:10px}.error-state .btn{margin-top:14px}
.tech-stack{display:flex;flex-wrap:wrap;gap:9px}.badge{background:var(--surface);border:1px solid var(--line);border-radius:11px;padding:8px 13px;font-weight:600;font-size:.82rem;display:flex;align-items:center;gap:7px;transition:.2s}.badge:hover{border-color:var(--primary);transform:translateY(-2px)}.badge i{font-size:1rem}
.links-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.link-card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:15px;display:flex;gap:12px;align-items:center;transition:.2s}.link-card:hover{transform:translateY(-3px);border-color:var(--primary)}
.link-card .lc-icon{width:42px;height:42px;flex-shrink:0;border-radius:11px;display:grid;place-items:center;font-size:1.05rem;color:#fff}.link-card h4{font-size:.9rem;margin-bottom:2px}.link-card p{font-size:.75rem;color:var(--muted);line-height:1.5}

/* Sidebar */
.sidebar{position:sticky;top:calc(var(--nav-height) + 20px);height:fit-content;min-width:0}
.widget{background:var(--surface);border-radius:16px;padding:21px;margin-bottom:20px;border:1px solid var(--line)}
.widget-title{font-size:1rem;margin-bottom:17px;padding-bottom:11px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:8px}.widget-title i{color:var(--primary)}
.about-widget{text-align:center}.about-avatar{width:90px;height:90px;border-radius:50%;margin:0 auto 13px;border:3px solid var(--primary);object-fit:cover;box-shadow:0 0 0 5px rgba(99,102,241,.09)}
.about-widget h3{font-size:1.1rem}.about-widget .about-role{color:var(--primary);font-size:.77rem;margin-bottom:9px}.about-widget p{color:var(--muted);font-size:.85rem;margin-bottom:13px}.text-link{color:var(--primary);font-size:.82rem;font-weight:700}.text-link:hover{text-decoration:underline}
.social-widget{display:flex;flex-wrap:wrap;gap:8px}.social-widget a{width:41px;height:41px;display:grid;place-items:center;border-radius:10px;background:var(--surface-2);color:var(--muted);font-size:1rem;transition:.2s}.social-widget a:hover{transform:translateY(-3px);background:var(--primary-strong);color:#fff}
.feed-widget{background:linear-gradient(145deg,rgba(99,102,241,.13),rgba(34,211,238,.055)),var(--surface)}.feed-widget p{color:var(--muted);font-size:.84rem;margin-bottom:15px}.feed-widget .btn{width:100%;margin-top:8px;font-size:.83rem}
.popular-posts{display:flex;flex-direction:column;gap:14px}.popular-post{display:flex;gap:11px;align-items:center}.popular-post img,.popular-thumb-placeholder{width:68px;height:64px;border-radius:10px;object-fit:cover;flex-shrink:0}.popular-thumb-placeholder{display:grid;place-items:center;background:var(--surface-2);color:var(--primary)}
.popular-post-content{min-width:0}.popular-post-content h4{font-size:.82rem;line-height:1.55;margin-bottom:4px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.popular-post-content h4 a:hover{color:var(--primary)}.popular-post-content time{font-size:.69rem;color:var(--muted)}
.links-list li{position:relative;margin-bottom:4px}.links-list a{display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-size:.84rem;padding:7px 0;transition:.2s}.links-list a::after{content:'\2039';color:var(--primary);font-size:1.1rem}.links-list a:hover{color:var(--primary);padding-inline-start:4px}

/* Pagination, footer and utilities */
.pagination{display:flex;justify-content:center;gap:10px;margin:35px 0}.pagination .btn{font-size:.85rem}
.footer{margin-top:55px;border-top:1px solid var(--line);background:var(--bg-soft);padding:50px 0 22px}
.footer-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:45px;margin-bottom:35px}.footer-section h3{font-size:1rem;margin-bottom:16px;color:var(--text)}.footer-section h3 i{color:var(--primary);margin-inline-end:6px}.footer-section p,.footer-section li{color:var(--muted);font-size:.84rem}.footer-section p{max-width:380px;margin-bottom:16px}.footer-section ul li{margin-bottom:6px}.footer-section ul a:hover{color:var(--primary)}
.footer-social{display:flex;gap:8px;flex-wrap:wrap}.footer-social a{width:37px;height:37px;display:grid;place-items:center;background:var(--surface);border:1px solid var(--line);border-radius:9px;color:var(--muted);transition:.2s}.footer-social a:hover{color:var(--primary);border-color:var(--primary);transform:translateY(-2px)}
.footer-bottom{display:flex;align-items:center;justify-content:space-between;gap:15px;padding-top:20px;border-top:1px solid var(--line);color:var(--muted);font-size:.78rem}.footer-bottom a{color:var(--primary)}
.extra-section{display:none}.back-to-top{position:fixed;bottom:24px;inset-inline-end:24px;width:45px;height:45px;background:var(--primary-strong);color:#fff;border:0;border-radius:12px;font-size:1rem;cursor:pointer;opacity:0;visibility:hidden;transform:translateY(10px);transition:.25s;z-index:900;box-shadow:0 10px 25px rgba(99,102,241,.3)}.back-to-top.visible{opacity:1;visibility:visible;transform:none}.back-to-top:hover{transform:translateY(-3px)}
.loader{display:inline-block;width:30px;height:30px;border:3px solid var(--line);border-top-color:var(--primary);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.loader-wrap{display:flex;justify-content:center;padding:30px;grid-column:1/-1}
.error-page{text-align:center;padding:80px 20px}.error-page h1{font:800 6rem/1 'Cairo',sans-serif;color:var(--primary);margin-bottom:20px}.error-page h2{font-size:1.6rem;margin-bottom:20px}
.toast{position:fixed;bottom:25px;left:50%;z-index:2500;transform:translate(-50%,20px);background:var(--text);color:var(--bg);padding:10px 18px;border-radius:11px;box-shadow:var(--shadow);font-size:.85rem;font-weight:700;opacity:0;visibility:hidden;transition:.25s;max-width:calc(100% - 30px);text-align:center}.toast.show{opacity:1;visibility:visible;transform:translate(-50%,0)}
html.js .reveal{opacity:0;transform:translateY(16px);transition:opacity .55s ease,transform .55s ease}html.js .reveal.in{opacity:1;transform:none}
html[dir='ltr'] body{direction:ltr}html[dir='ltr'] .links-list a::after{content:'\203A'}html[dir='ltr'] .read-more i{transform:rotate(180deg)}

/* Responsive and motion */
@media (max-width:1050px){
  .nav-container{gap:12px}.nav-links a{padding:8px 9px;font-size:.82rem}.brand-copy small{display:none}
  .main-wrapper{grid-template-columns:minmax(0,1fr) 280px;gap:22px}.hero-grid{gap:40px}
}
@media (max-width:860px){
  :root{--nav-height:64px}.container{width:min(100% - 30px,1180px)}
  .menu-toggle{display:inline-flex}.brand{margin-inline-end:auto}.nav-tools{margin-inline-start:0}
  .nav-links{display:none;position:absolute;top:100%;inset-inline:0;background:var(--surface);flex-direction:column;align-items:stretch;padding:13px 15px 18px;gap:4px;border-bottom:1px solid var(--line);box-shadow:var(--shadow)}
  .nav-links.active{display:flex}.nav-links a{padding:10px 13px;font-size:.9rem}.nav-links a i{width:18px;text-align:center}
  .main-wrapper{grid-template-columns:1fr;padding-top:30px}.sidebar{position:static;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.widget{margin:0}.about-widget{grid-row:span 2}
  .hero-grid{grid-template-columns:1fr;gap:55px}.hero-content{text-align:center}.hero-bio{margin-inline:auto}.hero-actions,.hero-badges,.header-social{justify-content:center}.hero-visual{max-width:500px}.header{padding:48px 0 65px}
  .home-posts .article-card:first-child{grid-template-columns:1fr}.home-posts .article-card:first-child .post-media{min-height:0;height:260px}.home-posts .article-card:first-child .post-title{font-size:1.5rem}
  .footer-grid{grid-template-columns:1.3fr 1fr 1fr;gap:25px}
}
@media (max-width:620px){
  .container{width:calc(100% - 26px)}.brand-copy strong{font-size:1rem}.brand-mark{width:37px;height:37px}.nav-tools{gap:5px}.icon-btn{width:38px;height:38px}.lang-toggle{padding-inline:9px}
  .logo{font-size:2.2rem;letter-spacing:-.7px}.hero-bio{font-size:.96rem}.hero-actions .btn{flex:1;min-width:145px}.code-content{font-size:.72rem;padding:19px}.profile-float{right:-3px;bottom:-28px}
  .home-posts{grid-template-columns:1fr}.home-posts .article-card:first-child{grid-column:auto}.home-posts .article-card:first-child .post-content{padding:23px}.post-media,.home-posts .article-card:first-child .post-media{height:205px}
  .section-title{font-size:1.25rem}.gh-grid,.links-grid,.related-grid{grid-template-columns:1fr}.gh-stats{grid-template-columns:repeat(2,1fr)}.project-controls{grid-template-columns:1fr 1fr}.search-field{grid-column:1/-1}.select-field{max-width:none;width:100%}
  .single-header,.single-content{padding:22px 19px}.single-header .post-title{font-size:1.55rem}.single-cover{max-height:280px}.post-body{font-size:1rem}.share-buttons>span{width:100%;margin-bottom:4px}
  .sidebar{grid-template-columns:1fr}.about-widget{grid-row:auto}.footer-grid{grid-template-columns:1fr 1fr}.footer-section:first-child{grid-column:1/-1}.footer-bottom{flex-direction:column;text-align:center}.back-to-top{bottom:18px;inset-inline-end:16px}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}html.js .reveal{opacity:1;transform:none}
}
@media print{
  .navbar,.header,.sidebar,.footer,.post-tools,.share-buttons,.related-posts,.comments-wrap,.back-to-top,.progress-bar,.breadcrumb{display:none!important}
  body{background:#fff;color:#111}.main-wrapper{display:block;width:100%;padding:0}.single-header,.single-content{border:0;padding:0}.post-body{color:#111}.post-body a{color:#111}.post-body pre{white-space:pre-wrap}.post-single{box-shadow:none}
}

