function msg(key){return (I18N[CURRENT_LANG] && I18N[CURRENT_LANG][key]) || I18N.ar[key] || key;}
function storageGet(key){try{return localStorage.getItem(key);}catch(e){return null;}}
function storageSet(key,value){try{localStorage.setItem(key,value);}catch(e){}}
function esc(value){return String(value == null ? '' : value).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function safeUrl(value){var url=String(value == null ? '' : value);return /^https?:\/\//i.test(url) ? url : '#';}
function on(id,event,handler){var el=document.getElementById(id);if(el)el.addEventListener(event,handler);}
function formatNumber(value){try{return new Intl.NumberFormat(CURRENT_LANG==='ar'?'ar-MA':'en-US').format(Number(value)||0);}catch(e){return String(value||0);}}
function formatDate(value){var date=new Date(value);if(!value||isNaN(date.getTime()))return '';try{return new Intl.DateTimeFormat(CURRENT_LANG==='ar'?'ar-MA':'en-US',{year:'numeric',month:'short',day:'numeric'}).format(date);}catch(e){return date.toLocaleDateString();}}
function notify(text){var el=document.getElementById('toast');if(!el)return;el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(function(){el.classList.remove('show');},2600);}
function copyText(text){
  if(navigator.clipboard&&window.isSecureContext)return navigator.clipboard.writeText(text);
  return new Promise(function(resolve,reject){
    var area=document.createElement('textarea');area.value=text;area.setAttribute('readonly','readonly');area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();
    try{if(document.execCommand('copy'))resolve();else reject(new Error('copy'));}catch(e){reject(e);}finally{document.body.removeChild(area);}
  });
}

/* Theme, language and navigation */
function applyTheme(theme,save){
  var light=String(theme||'dark').toLowerCase()==='light';document.documentElement.setAttribute('data-theme',light?'light':'dark');if(save!==false)storageSet('theme',light?'light':'dark');
  var icon=document.getElementById('themeIcon');if(icon)icon.className=light?'fas fa-moon':'fas fa-sun';
  var meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',light?'#f5f7fc':'#080d18');
}
function closeMenu(){var links=document.getElementById('navLinks');var button=document.getElementById('menuToggle');if(links)links.classList.remove('active');if(button){button.setAttribute('aria-expanded','false');var icon=button.querySelector('i');if(icon)icon.className='fas fa-bars';}}
function toggleMenu(){var links=document.getElementById('navLinks');var button=document.getElementById('menuToggle');if(!links||!button)return;var open=links.classList.toggle('active');button.setAttribute('aria-expanded',open?'true':'false');var icon=button.querySelector('i');if(icon)icon.className=open?'fas fa-xmark':'fas fa-bars';}
function applyLang(lang){
  CURRENT_LANG=lang==='en'?'en':'ar';storageSet('lang',CURRENT_LANG);document.documentElement.lang=CURRENT_LANG;document.documentElement.dir=CURRENT_LANG==='ar'?'rtl':'ltr';
  var label=document.getElementById('langLabel');if(label)label.textContent=CURRENT_LANG==='ar'?'EN':'ع';
  document.querySelectorAll('[data-i18n]').forEach(function(el){var key=el.getAttribute('data-i18n');if(I18N[CURRENT_LANG][key])el.textContent=I18N[CURRENT_LANG][key];});
  document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el){el.setAttribute('placeholder',msg(el.getAttribute('data-i18n-placeholder')));});
  document.querySelectorAll('[data-i18n-aria]').forEach(function(el){el.setAttribute('aria-label',msg(el.getAttribute('data-i18n-aria')));});
  renderStats();if(GH_LOADED){populateLanguages();renderProjects();}renderLinks();renderRecent();renderRelated();setReadTime();updateCopyButtons();
}
function setActiveNav(){
  var path=location.pathname.replace(/\/$/,'')||'/';document.querySelectorAll('.nav-links a').forEach(function(a){var href=a.getAttribute('href')||'';var linkPath=new URL(a.href,location.origin).pathname.replace(/\/$/,'')||'/';var active=path==='/'?href==='/':linkPath!=='/'&&path===linkPath;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
}

/* Accessible search dialog */
function openSearch(){var overlay=document.getElementById('searchOverlay');if(!overlay)return;lastFocused=document.activeElement;overlay.classList.add('open');overlay.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';var button=document.getElementById('searchToggle');if(button)button.setAttribute('aria-expanded','true');setTimeout(function(){var input=document.getElementById('searchInput');if(input)input.focus();},40);}
function closeSearch(){var overlay=document.getElementById('searchOverlay');if(!overlay||!overlay.classList.contains('open'))return;overlay.classList.remove('open');overlay.setAttribute('aria-hidden','true');document.body.style.overflow='';var button=document.getElementById('searchToggle');if(button)button.setAttribute('aria-expanded','false');if(lastFocused&&lastFocused.focus)lastFocused.focus();}
function trapSearchFocus(event){
  var overlay=document.getElementById('searchOverlay');if(event.key==='Escape'){closeSearch();closeMenu();return;}if(event.key!=='Tab'||!overlay||!overlay.classList.contains('open'))return;
  var items=Array.prototype.slice.call(overlay.querySelectorAll('button,a[href],input')).filter(function(el){return !el.disabled&&el.offsetParent!==null;});if(!items.length)return;
  var first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
}
function scrollToTop(){var reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;window.scrollTo({top:0,behavior:reduced?'auto':'smooth'});}

/* Post reading tools and sharing */
function changeFont(delta){var body=document.getElementById('postBody');if(!body)return;var current=parseInt(storageGet('postFontSize')||'100',10);current=Math.min(140,Math.max(80,current+delta));body.style.fontSize=current+'%';storageSet('postFontSize',String(current));}
function restoreFont(){var body=document.getElementById('postBody');var size=parseInt(storageGet('postFontSize')||'100',10);if(body&&size>=80&&size<=140&&size!==100)body.style.fontSize=size+'%';}
function setReadTime(){var body=document.getElementById('postBody');if(!body)return;var text=(body.innerText||'').trim();var words=text?text.split(/\s+/).length:0;var mins=Math.max(1,Math.round(words/(CURRENT_LANG==='ar'?180:220)));document.querySelectorAll('.read-time').forEach(function(el){el.innerHTML='<i class="far fa-clock"></i> '+mins+' '+esc(msg('minutes'));});}
function nativeShare(){var data={title:document.title,url:location.href};if(navigator.share)navigator.share(data).catch(function(){});else copyText(location.href).then(function(){notify(msg('copied'));}).catch(function(){notify(msg('copy_error'));});}
function bindShare(){var url=encodeURIComponent(location.href),title=encodeURIComponent(document.title);var map={facebook:'https://www.facebook.com/sharer/sharer.php?u='+url,twitter:'https://twitter.com/intent/tweet?url='+url+'&text='+title,whatsapp:'https://api.whatsapp.com/send?text='+title+'%20'+url,telegram:'https://t.me/share/url?url='+url+'&text='+title,linkedin:'https://www.linkedin.com/sharing/share-offsite/?url='+url};document.querySelectorAll('[data-share]').forEach(function(button){button.addEventListener('click',function(){var type=button.getAttribute('data-share');if(type==='native'){nativeShare();return;}if(type==='copy'){copyText(location.href).then(function(){notify(msg('copied'));}).catch(function(){notify(msg('copy_error'));});return;}if(map[type])window.open(map[type],'_blank','noopener,noreferrer,width=760,height=620');});});}
function buildTOC(){
  var body=document.getElementById('postBody'),list=document.getElementById('tocList'),box=document.getElementById('tocBox');if(!body||!list)return;var headings=body.querySelectorAll('h2,h3');if(!headings.length){if(box)box.hidden=true;return;}var html='';
  headings.forEach(function(heading,index){if(!heading.id)heading.id='section-'+(index+1);html+='<a class="'+(heading.tagName==='H3'?'lvl-3':'')+'" href="#'+esc(heading.id)+'">'+esc(heading.textContent)+'</a>';});list.innerHTML=html;
  if('IntersectionObserver' in window){var links=list.querySelectorAll('a');var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){links.forEach(function(link){link.classList.remove('active');});var index=Array.prototype.indexOf.call(headings,entry.target);if(links[index])links[index].classList.add('active');}});},{rootMargin:'-15% 0px -70% 0px',threshold:0});headings.forEach(function(heading){observer.observe(heading);});}
}
function updateCopyButtons(){document.querySelectorAll('.copy-code').forEach(function(button){if(!button.dataset.copied)button.textContent=msg('copy_code');});}
function addCopyButtons(){document.querySelectorAll('.post-body pre').forEach(function(pre){if(pre.querySelector('.copy-code'))return;var button=document.createElement('button');button.className='copy-code';button.type='button';button.textContent=msg('copy_code');button.addEventListener('click',function(){var clone=pre.cloneNode(true);var copy=clone.querySelector('.copy-code');if(copy)copy.remove();copyText(clone.textContent.trim()).then(function(){button.dataset.copied='true';button.textContent=msg('copied_code');setTimeout(function(){button.dataset.copied='';button.textContent=msg('copy_code');},1600);}).catch(function(){notify(msg('copy_error'));});});pre.appendChild(button);});}
function injectPostSchema(){
  var body=document.getElementById('postBody');if(!body||!document.querySelector("article[itemtype='https://schema.org/BlogPosting']"))return;var time=document.querySelector('time[datetime]'),title=document.querySelector('.post-single h1'),image=document.querySelector('.single-cover');if(!time||!title)return;
  var labels=document.getElementById('postLabels');var data={'@context':'https://schema.org','@type':'BlogPosting',mainEntityOfPage:{'@type':'WebPage','@id':location.href.split('#')[0]},headline:title.textContent,datePublished:time.getAttribute('datetime'),dateModified:time.getAttribute('datetime'),inLanguage:CURRENT_LANG,author:{'@type':'Person',name:'werlist99',url:BLOG_URL+'/'},publisher:{'@type':'Organization',name:'werlist99',logo:{'@type':'ImageObject',url:'https://avatars.githubusercontent.com/u/245860205?v=4'}}};
  var excerpt=document.querySelector('.single-excerpt');if(excerpt)data.description=excerpt.textContent;if(image)data.image=image.src;if(labels)data.keywords=labels.textContent.split('|').filter(Boolean).join(', ');
  var script=document.createElement('script');script.type='application/ld+json';script.id='postSchema';script.textContent=JSON.stringify(data);document.head.appendChild(script);
}

/* GitHub repositories */
function ghCacheGet(key,stale){try{var raw=localStorage.getItem(key);if(!raw)return null;var obj=JSON.parse(raw);if(!stale&&Date.now()-obj.t>GH_CACHE_HOURS*3600000)return null;return obj.d;}catch(e){return null;}}
function ghCacheSet(key,data){try{localStorage.setItem(key,JSON.stringify({t:Date.now(),d:data}));}catch(e){}}
function renderStats(){var box=document.getElementById('ghStats');if(!box||!GH_STATS)return;box.innerHTML='<div class="gh-stat"><b>'+esc(formatNumber(GH_STATS.repos))+'</b><span>'+esc(msg('repos'))+'</span></div><div class="gh-stat"><b>'+esc(formatNumber(GH_STATS.stars))+'</b><span>'+esc(msg('stars'))+'</span></div><div class="gh-stat"><b>'+esc(formatNumber(GH_STATS.followers))+'</b><span>'+esc(msg('followers'))+'</span></div><div class="gh-stat"><b>'+esc(formatNumber(GH_STATS.following))+'</b><span>'+esc(msg('following'))+'</span></div>';}
function langColor(lang){var map={Python:'#3776ab',JavaScript:'#d6b900',TypeScript:'#3178c6',PHP:'#777bb4',Swift:'#ffac45','C++':'#6189b5',C:'#777',HTML:'#e34f26',CSS:'#1572b6',Shell:'#89e051',Java:'#b07219',Go:'#00add8',Vue:'#42b883',Dart:'#0175c2'};return map[lang]||'#8b5cf6';}
function populateLanguages(){var select=document.getElementById('repoLanguage');if(!select)return;var selected=select.value;var languages=[];GH_REPOS.forEach(function(repo){if(repo.language&&languages.indexOf(repo.language)===-1)languages.push(repo.language);});languages.sort();select.innerHTML='';var all=document.createElement('option');all.value='';all.textContent=msg('all_languages');select.appendChild(all);languages.forEach(function(language){var option=document.createElement('option');option.value=language;option.textContent=language;select.appendChild(option);});select.value=languages.indexOf(selected)!==-1?selected:'';}
function filteredRepos(){var search=document.getElementById('repoSearch'),language=document.getElementById('repoLanguage'),sort=document.getElementById('repoSort');var query=search?search.value.trim().toLowerCase():'';var lang=language?language.value:'';var order=sort?sort.value:'stars';return GH_REPOS.filter(function(repo){var text=(repo.name+' '+(repo.description||'')+' '+(repo.topics||[]).join(' ')).toLowerCase();return(!query||text.indexOf(query)!==-1)&&(!lang||repo.language===lang);}).sort(function(a,b){if(order==='name')return a.name.localeCompare(b.name);if(order==='updated')return new Date(b.updated_at)-new Date(a.updated_at);return(b.stargazers_count-a.stargazers_count)||(new Date(b.updated_at)-new Date(a.updated_at));});}
function renderProjects(){
  var box=document.getElementById('ghProjects');if(!box||!GH_LOADED)return;var repos=filteredRepos(),count=document.getElementById('repoCount');if(count){var shown=Math.min(repos.length,GH_MAX_REPOS);count.textContent=formatNumber(shown)+(shown!==GH_REPOS.length?' / '+formatNumber(GH_REPOS.length):'');}
  if(!repos.length){box.innerHTML='<div class="empty-state"><i class="fas fa-folder-open"></i><p>'+esc(msg('no_repos'))+'</p></div>';return;}var html='';
  repos.slice(0,GH_MAX_REPOS).forEach(function(repo){var topics=(repo.topics||[]).slice(0,3).map(function(topic){return '<span class="gh-topic">'+esc(topic)+'</span>';}).join('');html+='<article class="gh-card"><div class="gh-head"><i class="fas fa-book-open"></i><h3><a href="'+esc(safeUrl(repo.html_url))+'" target="_blank" rel="noopener noreferrer">'+esc(repo.name)+'</a></h3></div><p class="gh-desc">'+esc(repo.description||msg('no_description'))+'</p><div class="gh-foot">'+(repo.language?'<span class="lang"><span class="lang-dot" style="background:'+esc(langColor(repo.language))+'"></span>'+esc(repo.language)+'</span>':'')+'<span><i class="far fa-star"></i> '+esc(formatNumber(repo.stargazers_count))+'</span><span><i class="fas fa-code-branch"></i> '+esc(formatNumber(repo.forks_count))+'</span></div>'+(topics?'<div class="gh-topics">'+topics+'</div>':'')+'<div class="gh-updated">'+esc(msg('updated'))+': '+esc(formatDate(repo.updated_at))+'</div></article>';});box.innerHTML=html;
}
function injectItemList(repos){if(!repos||!repos.length)return;var old=document.getElementById('repoSchema');if(old)old.remove();var items=repos.slice(0,GH_MAX_REPOS).map(function(repo,index){return {'@type':'ListItem',position:index+1,name:repo.name,url:repo.html_url};});var script=document.createElement('script');script.type='application/ld+json';script.id='repoSchema';script.textContent=JSON.stringify({'@context':'https://schema.org','@type':'ItemList',itemListElement:items});document.head.appendChild(script);}
function showGitHubError(){var box=document.getElementById('ghProjects');if(!box)return;box.innerHTML='<div class="error-state"><i class="fas fa-cloud-arrow-down"></i><p>'+esc(msg('gh_error'))+'</p><button class="btn btn-primary" id="repoRetry" type="button"><i class="fas fa-rotate-right"></i>'+esc(msg('retry'))+'</button> <a class="btn btn-ghost" href="https://github.com/'+esc(GH_USER)+'" target="_blank" rel="noopener noreferrer">'+esc(msg('view_github'))+'</a></div>';on('repoRetry','click',loadGitHub);}
function fetchJson(url){return fetch(url).then(function(response){if(!response.ok)throw new Error('HTTP '+response.status);return response.json();});}
function loadGitHub(){
  if(!document.getElementById('ghProjects'))return;var repoKey='gh:v6:repos:'+GH_USER,statsKey='gh:v6:stats:'+GH_USER;var cachedRepos=ghCacheGet(repoKey),cachedStats=ghCacheGet(statsKey);
  if(cachedRepos&&cachedStats){GH_REPOS=cachedRepos;GH_STATS=cachedStats;GH_LOADED=true;populateLanguages();renderStats();renderProjects();injectItemList(cachedRepos);return;}
  var box=document.getElementById('ghProjects');box.innerHTML='<div class="loader-wrap"><span class="loader"></span></div>';
  Promise.all([fetchJson('https://api.github.com/users/'+GH_USER),fetchJson('https://api.github.com/users/'+GH_USER+'/repos?sort=updated&per_page=100')]).then(function(results){var user=results[0],repos=results[1];if(!Array.isArray(repos))throw new Error('Invalid repositories');GH_REPOS=repos.filter(function(repo){return !repo.fork;});GH_STATS={repos:user.public_repos||repos.length,stars:repos.reduce(function(total,repo){return total+(repo.stargazers_count||0);},0),followers:user.followers||0,following:user.following||0};GH_LOADED=true;populateLanguages();renderStats();renderProjects();injectItemList(GH_REPOS);ghCacheSet(statsKey,GH_STATS);ghCacheSet(repoKey,GH_REPOS);}).catch(function(){var staleRepos=ghCacheGet(repoKey,true),staleStats=ghCacheGet(statsKey,true);if(staleRepos&&staleStats){GH_REPOS=staleRepos;GH_STATS=staleStats;GH_LOADED=true;populateLanguages();renderStats();renderProjects();}else showGitHubError();});
}
function renderLinks(){var box=document.getElementById('linkGrid');if(!box)return;var html='';CURATED_LINKS.forEach(function(link){var icon=/^[a-z0-9\- ]+$/i.test(link.icon||'')?link.icon:'fas fa-star';html+='<a class="link-card" href="'+esc(safeUrl(link.url))+'" target="_blank" rel="noopener noreferrer"><span class="lc-icon" style="background:'+esc(link.color)+'"><i class="'+esc(icon)+'"></i></span><span><h4>'+esc(link.name)+'</h4><p>'+esc(link[CURRENT_LANG])+'</p></span></a>';});box.innerHTML=html;}

/* Blogger JSON feeds */
function loadFeed(url,onError){var script=document.createElement('script');script.src=url;script.async=true;script.onerror=function(){if(onError)onError();script.remove();};document.body.appendChild(script);}
function feedEntry(entry){var link='';for(var i=0;i<(entry.link||[]).length;i++){if(entry.link[i].rel==='alternate'){link=entry.link[i].href;break;}}return{title:entry.title&&entry.title.$t?entry.title.$t:'',link:link,thumb:entry.media$thumbnail?entry.media$thumbnail.url:'',published:entry.published?entry.published.$t:''};}
function showRecent(json){LAST_RECENT=json;renderRecent();}
function renderRecent(){var box=document.getElementById('recentPosts');if(!box||!LAST_RECENT)return;var entries=LAST_RECENT.feed&&LAST_RECENT.feed.entry?LAST_RECENT.feed.entry:[];if(!entries.length){box.innerHTML='<p class="section-subtitle">'+esc(msg('no_posts'))+'</p>';return;}var html='';entries.slice(0,5).forEach(function(entry){var item=feedEntry(entry),thumb=item.thumb?safeUrl(item.thumb.replace('/s72-c/','/w160-h160-c/')):'';html+='<article class="popular-post">'+(thumb&&thumb!=='#'?'<img alt="" decoding="async" loading="lazy" src="'+esc(thumb)+'"/>':'<span class="popular-thumb-placeholder"><i class="fas fa-newspaper"></i></span>')+'<div class="popular-post-content"><h4><a href="'+esc(safeUrl(item.link))+'">'+esc(item.title)+'</a></h4><time>'+esc(formatDate(item.published))+'</time></div></article>';});box.innerHTML=html;}
function showRelated(json){LAST_RELATED=json;renderRelated();}
function renderRelated(){var box=document.getElementById('relatedPosts');if(!box||!LAST_RELATED)return;var entries=LAST_RELATED.feed&&LAST_RELATED.feed.entry?LAST_RELATED.feed.entry:[];var current=location.href.split('#')[0].replace(/\/$/,'');var html='',used=0;for(var i=0;i<entries.length&&used<4;i++){var item=feedEntry(entries[i]);if(item.link.split('#')[0].replace(/\/$/,'')===current)continue;var thumb=item.thumb?safeUrl(item.thumb.replace('/s72-c/','/w240-h240-c/')):'';html+='<article class="related-card">'+(thumb&&thumb!=='#'?'<img alt="" decoding="async" loading="lazy" src="'+esc(thumb)+'"/>':'<span class="related-thumb-placeholder"><i class="fas fa-newspaper"></i></span>')+'<div class="related-card-content"><h4><a href="'+esc(safeUrl(item.link))+'">'+esc(item.title)+'</a></h4></div></article>';used++;}box.innerHTML=html||'<p class="section-subtitle">'+esc(msg('no_posts'))+'</p>';}

/* Motion and boot */
function initReveal(){var elements=document.querySelectorAll('.hub-section,.home-posts .article-card,.widget');if(!('IntersectionObserver' in window)||(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)){elements.forEach(function(el){el.classList.add('reveal','in');});return;}var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('in');observer.unobserve(entry.target);}});},{threshold:.05,rootMargin:'0px 0px -20px'});elements.forEach(function(el){el.classList.add('reveal');observer.observe(el);});}
function bindControls(){
  on('themeToggle','click',function(){applyTheme(document.documentElement.getAttribute('data-theme')==='light'?'dark':'light');});
  on('langToggle','click',function(){applyLang(CURRENT_LANG==='ar'?'en':'ar');});on('menuToggle','click',toggleMenu);on('backToTop','click',scrollToTop);
  on('searchToggle','click',openSearch);on('searchClose','click',closeSearch);on('searchOverlay','click',function(event){if(event.target.id==='searchOverlay')closeSearch();});
  on('fontDecrease','click',function(){changeFont(-10);});on('fontIncrease','click',function(){changeFont(10);});on('printPost','click',function(){window.print();});on('copyPostLink','click',function(){copyText(location.href).then(function(){notify(msg('copied'));}).catch(function(){notify(msg('copy_error'));});});
  on('repoSearch','input',renderProjects);on('repoLanguage','change',renderProjects);on('repoSort','change',renderProjects);
  document.addEventListener('keydown',trapSearchFocus);document.addEventListener('click',function(event){var nav=document.getElementById('navbar');if(nav&&!nav.contains(event.target))closeMenu();});document.querySelectorAll('.nav-links a').forEach(function(link){link.addEventListener('click',closeMenu);});window.addEventListener('resize',function(){if(window.innerWidth>860)closeMenu();});
}
var scrollScheduled=false;window.addEventListener('scroll',function(){if(scrollScheduled)return;scrollScheduled=true;window.requestAnimationFrame(function(){var y=window.scrollY||document.documentElement.scrollTop;var back=document.getElementById('backToTop');if(back)back.classList.toggle('visible',y>450);var progress=document.getElementById('progressBar');if(progress){var root=document.documentElement,max=root.scrollHeight-root.clientHeight;progress.style.width=(max>0?Math.min(100,y/max*100):0)+'%';}scrollScheduled=false;});},{passive:true});

document.addEventListener('DOMContentLoaded',function(){
  bindControls();applyTheme(storageGet('theme')||document.documentElement.getAttribute('data-theme')||'dark',false);restoreFont();applyLang(storageGet('lang')||'ar');
  var year=document.getElementById('currentYear');if(year)year.textContent=new Date().getFullYear();setActiveNav();loadGitHub();initReveal();
  if(document.getElementById('postBody')){buildTOC();addCopyButtons();setReadTime();injectPostSchema();bindShare();}
  loadFeed('/feeds/posts/default?alt=json-in-script&max-results=5&callback=showRecent',function(){var box=document.getElementById('recentPosts');if(box)box.innerHTML='<p class="section-subtitle">'+esc(msg('load_error'))+'</p>';});
  var labels=document.getElementById('postLabels');if(labels){var label=labels.textContent.split('|')[0].trim();if(label)loadFeed('/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json-in-script&max-results=8&callback=showRelated',function(){var box=document.getElementById('relatedPosts');if(box)box.innerHTML='<p class="section-subtitle">'+esc(msg('load_error'))+'</p>';});else{var section=document.getElementById('relatedSection');if(section)section.hidden=true;}}
});
//
